[9634] = { "Подоба жахливого ведмедя", "Набути подоби жахливого ведмедя, що збільшує силу атаки на {1}, броню від предметів на {2}% та здоров'я на {3}. Також захищає заклинача від ефектів поліморфії та дозволяє використання ведмежих здібностей.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#Power by {1}#items by {2}%#Health by {3}", "Невразливість до ефектів поліморфії. Збільшує силу атаки на {1}, броню від предметів на {2}% та здоров'я на {3}.#Power by {1}#items by {2}%#Health by {3}", en="Dire Bear Form" },
[24858] = { "Подоба місячного совуха", "Набути подоби місячного совуха. У цій подобі ймовірність спрацювання \"Передвістя ясності\" збільшується на {1}%, броня від предметів збільшується на {2}%, а ймовірність критичного удару всіх учасників групи в межах {3} м збільшується на {4}% (не поєднується з ефектом \"Вожак зграї\"). Також надає невразливість до ефектів поліморфії та не дозволяє вимовляти цілющі закляття.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#trigger by {1}%,#items by {2}%,#within {3} y#increased by {4}%", "Невразливість до ефектів поліморфії. Ймовірність спрацювання \"Передвістя ясності\" збільшено. Броню від предметів збільшено на {1}%.#by {1}%", en="Moonkin Form" },
[783] = { "Мандрівна подоба", "Набути мандрівної подоби, що збільшує швидкість руху на {1}%. Також захищає заклинача від ефектів поліморфії. Можна використовувати лише просто неба.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#speed by {1}%", "Невразливість до ефектів поліморфії. Швидкість руху збільшено на {1}%.#by {1}%", en="Travel Form" },

